<script setup lang="ts">
import { ArrowLeft, ArrowRight, BookmarkPlus, Sparkles } from '@lucide/vue'
import type { PublicCatalog } from '~~/shared/types/catalog'
const route=useRoute()
const {data:catalog}=await useFetch<PublicCatalog>('/api/public/catalog',{key:'public-catalog'})
const item=computed(()=>catalog.value?.portfolio.find((entry)=>entry.slug===route.params.slug))
if(!item.value)throw createError({statusCode:404,statusMessage:'Cette référence n’existe pas ou n’est plus publiée.'})
const title=`${item.value.title} — Inspiration nail art`
const description=item.value.description||`${item.value.category} · ${item.value.style} · ${item.value.technique}`
const coverImageUrl=usePublicAssetUrl(item.value.imageUrls[0])
useSeoMeta({title,description,ogTitle:title,ogDescription:description,ogType:'article',ogImage:coverImageUrl,twitterCard:'summary_large_image'})
const bookingQuery=computed(()=>({path:'/reservation',query:{reference:item.value?.id,service:item.value?.serviceSlug}}))
</script>

<template><div v-if="item" class="container-page look-detail"><NuxtLink class="back-link" to="/realisations"><ArrowLeft :size="15"/> Toutes les inspirations</NuxtLink><div v-if="catalog?.demo" class="demo-note">Image éditoriale générée pour l’aperçu : ce n’est pas une pose réalisée par le salon.</div><div class="look-detail__layout"><section class="look-gallery" :aria-label="`Galerie ${item.title}`"><figure v-for="(image,index) in item.imageUrls" :key="image"><img :src="image" :alt="catalog?.demo?`Image d’inspiration ${item.title}, vue ${index+1}`:`${item.title}, vue ${index+1}`" width="900" height="1100" :fetchpriority="index===0?'high':'auto'" loading="lazy" decoding="async"></figure><div v-if="!item.imageUrls.length" class="look-placeholder"><Sparkles :size="28"/><span>Aucune image publiée</span></div></section><aside class="look-detail__copy"><span class="eyebrow">{{item.category}}<template v-if="item.style"> · {{item.style}}</template></span><h1 class="display">{{item.title}}</h1><p class="look-lead">{{item.description}}</p><p v-if="item.trend" class="trend-note"><Sparkles :size="15"/> Repère de tendance</p><dl class="style-facts"><div><dt>Couleur</dt><dd>{{item.color||'Non précisée'}}</dd></div><div><dt>Forme</dt><dd>{{item.shape||'Non précisée'}}</dd></div><div><dt>Longueur</dt><dd>{{item.length||'Non précisée'}}</dd></div><div><dt>Technique</dt><dd>{{item.technique||'Non précisée'}}</dd></div></dl><div v-if="item.tags.length" class="look-tags"><span v-for="tag in item.tags" :key="tag">#{{tag}}</span></div><p v-if="item.serviceSlug" class="service-related">Prestation associée : <NuxtLink :to="`/prestations/${item.serviceSlug}`">découvrir la fiche <ArrowRight :size="13"/></NuxtLink></p><NuxtLink class="btn btn-primary" :to="bookingQuery"><BookmarkPlus :size="16"/> Je souhaite cette pose</NuxtLink><p class="detail-footnote">La référence sera jointe à votre demande de rendez-vous ; la scène 3D du site ne simule pas l’application de cette pose sur une photo.</p></aside></div></div></template>

